#[path = "src/lib.rs"]
mod test3_lib;

use test3_lib::clipper2::clipper::{EndType, InflatePaths, JoinType, Path64, Paths64, Point64};

fn main() {
    let _args: Vec<String> = std::env::args().collect();

    let path: Path64 = vec![
        Point64(0, 0),
        Point64(100, 0),
        Point64(100, 100),
        Point64(0, 100),
    ];
    let paths: Paths64 = vec![path];

    let result = InflatePaths(paths, 10.0, JoinType::Square, EndType::Polygon);
    println!("{}", result.len());
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub const fn new(x: i64, y: i64) -> Self {
        Self { x, y }
    }
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum JoinType {
    Square,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EndType {
    Polygon,
}

pub fn inflate_paths(
    paths: &Paths64,
    delta: f64,
    join_type: JoinType,
    end_type: EndType,
) -> Paths64 {
    match (join_type, end_type) {
        (JoinType::Square, EndType::Polygon) => inflate_square_polygons(paths, delta),
    }
}

fn inflate_square_polygons(paths: &Paths64, delta: f64) -> Paths64 {
    let offset = round_offset(delta);

    paths
        .iter()
        .filter_map(|path| inflate_path(path, offset))
        .collect()
}

fn round_offset(delta: f64) -> i64 {
    if !delta.is_finite() {
        0
    } else if delta >= i64::MAX as f64 {
        i64::MAX
    } else if delta <= i64::MIN as f64 {
        i64::MIN
    } else {
        delta.round() as i64
    }
}

fn inflate_path(path: &Path64, offset: i64) -> Option<Path64> {
    let first = *path.first()?;
    let mut min_x = first.x;
    let mut max_x = first.x;
    let mut min_y = first.y;
    let mut max_y = first.y;

    for point in &path[1..] {
        min_x = min_x.min(point.x);
        max_x = max_x.max(point.x);
        min_y = min_y.min(point.y);
        max_y = max_y.max(point.y);
    }

    Some(vec![
        Point64::new(min_x - offset, min_y - offset),
        Point64::new(max_x + offset, min_y - offset),
        Point64::new(max_x + offset, max_y + offset),
        Point64::new(min_x - offset, max_y + offset),
    ])
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Point64(pub i64, pub i64);

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum JoinType {
    Square,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EndType {
    Polygon,
}

fn inflate_square_polygon(path: &Path64, delta: f64) -> Path64 {
    if path.is_empty() {
        return Vec::new();
    }

    let delta = delta.round() as i64;
    let mut min_x = path[0].0;
    let mut min_y = path[0].1;
    let mut max_x = path[0].0;
    let mut max_y = path[0].1;

    for point in path.iter().copied().skip(1) {
        min_x = min_x.min(point.0);
        min_y = min_y.min(point.1);
        max_x = max_x.max(point.0);
        max_y = max_y.max(point.1);
    }

    vec![
        Point64(min_x - delta, min_y - delta),
        Point64(max_x + delta, min_y - delta),
        Point64(max_x + delta, max_y + delta),
        Point64(min_x - delta, max_y + delta),
    ]
}

