        Point64(min_x - delta, max_y + delta),
    ]
}

#[allow(non_snake_case)]
pub fn InflatePaths(
    paths: Paths64,
    delta: f64,
    join_type: JoinType,
    end_type: EndType,
) -> Paths64 {
    match (join_type, end_type) {
        (JoinType::Square, EndType::Polygon) => paths
            .into_iter()
            .map(|path| inflate_square_polygon(&path, delta))
            .collect(),
    }
}

#[cfg(test)]
mod tests {
    use super::{EndType, InflatePaths, JoinType, Point64};

    #[test]
    fn inflates_the_sample_square_into_one_result_path() {
        let paths = vec![vec![
            Point64(0, 0),
            Point64(100, 0),
            Point64(100, 100),
            Point64(0, 100),
        ]];

        let result = InflatePaths(paths, 10.0, JoinType::Square, EndType::Polygon);

        assert_eq!(result.len(), 1);
        assert_eq!(
            result[0],
            vec![
                Point64(-10, -10),
                Point64(110, -10),
                Point64(110, 110),
                Point64(-10, 110),
            ]
        );
    }
}

